import express, { Express } from 'express';
import { ListStockLevelsUseCase } from '../../application/use-cases/ListStockLevelsUseCase';
import { StockReservationService } from '../../domain/services/StockReservationService';
import { StockController } from '../http/StockController';
import { errorMiddleware, notFoundMiddleware } from '../http/errorMiddleware';
import { InMemoryOrderRepository } from '../persistence/InMemoryOrderRepository';
import { InMemoryProductRepository } from '../persistence/InMemoryProductRepository';
import { seedCatalogue } from '../persistence/seedCatalogue';
import { buildOrderController } from './orderModule';

/** Composition root: builds the in-memory stores, use cases and HTTP routes. */
export function createApp(): Express {
  const products = new InMemoryProductRepository();
  seedCatalogue(products);
  const orders = new InMemoryOrderRepository();
  const stock = new StockReservationService(products);

  const app = express();
  app.use(express.json());
  app.use('/orders', buildOrderController(orders, stock).routes());
  app.use('/stock', new StockController(new ListStockLevelsUseCase(products)).routes());
  app.use(notFoundMiddleware);
  app.use(errorMiddleware);
  return app;
}

